mapper.select:
SELECT routine_id, member_id, routine_name, description, created_at, updated_at
FROM routines
WHERE routine_id = #{routineId}
  AND member_id = #{memberId}

mapper.update:
UPDATE routines
SET routine_name = #{routineName},
    description = #{description,jdbcType=VARCHAR},
    updated_at = SYSDATE
WHERE routine_id = #{routineId}
  AND member_id = #{memberId}

mapper.delete:
DELETE FROM routines
WHERE routine_id = #{routineId}
  AND member_id = #{memberId}
